local({
  set.seed(72)
  subjects <- rnorm(12, sd = 2)
  wide <- data.frame(Subject = paste0("S", 1:12), Baseline = 10 + subjects + rnorm(12), Baseline2 = 12 + subjects + rnorm(12), aCSF1 = 14 + subjects + rnorm(12), check.names = FALSE)
  wide$Baseline[c(2, 5)] <- NA; wide$Baseline2[3] <- NA
  d <- wide_to_long(wide, c("Baseline", "Baseline2", "aCSF1"), "Subject")
  cfg <- list(method = "mixed", y = "response", group = "group", id = "subject", adjustment = "sidak", comparisons = "control", control = "Baseline", sphericity = "gg")
  r <- run_analysis(d, cfg); x <- r$tables$descriptive_statistics
  check(identical(x$n, c(10L, 11L, 12L)) && identical(x$missing, c(2L, 1L, 0L)), "Descriptives count blank cells per worksheet column without discarding other conditions")
  check(near(x$minimum[1], min(wide$Baseline, na.rm = TRUE)) && near(x$maximum[2], max(wide$Baseline2, na.rm = TRUE)), "Descriptive minimum and maximum match original entered measurements")
  check(r$tables$data_summary$subjects == 12 && r$tables$data_summary$missing_values == 3 && r$tables$data_summary$treatments == 3, "Data summary reports entered subjects, selected conditions and missing measurements")
  absent <- d[-2, ]; rr <- run_analysis(absent, cfg)
  check(rr$tables$data_summary$missing_values == 3, "Long-format absent subject-condition records count as missing measurements")
  p <- r$tables$posthoc
  check(near(p$mean_1 - p$mean_2, p$estimate) && all(p$mean_type == "Predicted (LS)") && identical(p$n1, c(10L, 10L)) && identical(p$n2, c(11L, 12L)), "Comparison details report the actual pairwise-model predicted means and observation counts")
  overall <- r$tables$predicted_means
  design <- model.matrix(~group, data.frame(group = factor(overall$group, levels = levels(r$data$group))))
  check(near(overall$mean, design %*% mixed_beta(r$fit)), "Overall predicted means match the fitted fixed-effect design matrix")
  rm <- run_analysis(d, modifyList(cfg, list(method = "rm_anova")))
  check(all(rm$tables$descriptive_statistics$n == c(10, 11, 12)) && all(rm$tables$summary$n == 9), "Descriptive input counts remain separate from complete-case ANOVA counts")
  sheets <- result_sheets(r, worksheet = list(name = "Experiment", layout = "wide", data = wide))
  f <- sheet_frame(sheets$descriptive_statistics)
  check(identical(names(f)[-1], c("Baseline", "Baseline2", "aCSF1")) && all(c("Minimum", "Maximum", "Number of missing values") %in% f[[1]]), "Descriptive result sheet preserves worksheet order and screenshot-style statistic rows")
  tab <- sheet_frame(sheets$tabular_results)
  check(tab[tab[[1]] == "Table Analyzed", 2] == "Experiment" && all(c("Random effects", "Was the matching effective?", "Data summary") %in% tab[[1]]), "Mixed-model tabular sheet combines treatment, random effects, matching and data summary")
  comp <- sheet_frame(sheets$multiple_comparisons)
  check(all(c("Number of families", "Number of comparisons per family", "Test details") %in% comp[[1]]) && any(comp[[1]] == "Baseline vs. Baseline2"), "Comparison sheet includes family metadata, ordered contrasts and detailed means/SE/n/t/df")
  norm <- run_analysis(d, modifyList(cfg, list(method = "normality")))
  nf <- sheet_frame(result_sheets(norm)$tabular_results)
  check(all(c("Test for normal distribution", "Test for lognormal distribution", "K2", "W", "Number of zeros", "Number of negative values") %in% nf[[1]]), "Normality sheet arranges both tests and impossible-value counts by data column")
  out <- run_analysis(d, modifyList(cfg, list(method = "outliers", rout_q = .01)))
  worksheet <- list(name = "Experiment", layout = "wide", columns = c("Baseline", "Baseline2", "aCSF1"), data = wide)
  os <- result_sheets(out, worksheet = worksheet)
  check(identical(names(os), c("summary", "outliers", "cleaned_data")) && identical(cleaned_worksheet(out, worksheet)$Subject, wide$Subject), "ROUT sheets include Summary/Outliers/Cleaned data and reconstruct original subject rows")
  hidden <- r; hidden$config$report_descriptive <- FALSE; hidden$config$report_adjusted_p <- FALSE
  hs <- result_sheets(hidden)
  check(!"descriptive_statistics" %in% names(hs) && !any(grepl("Adjusted", hs$multiple_comparisons$columns)), "Reporting switches remain effective in arranged sheets")
  exports <- result_export_tables(r, worksheet = worksheet)
  check(all(c("sheet_tabular_results", "sheet_multiple_comparisons", "posthoc") %in% names(exports)) && identical(exports$posthoc$p_value, r$tables$posthoc$p_value), "Exports offer arranged tables and retain raw numerical comparison precision")
  for (method in c("anova", "welch_anova", "rm_anova", "mixed", "log_mixed", "kruskal", "friedman", "normality", "summary", "outliers")) {
    z <- run_analysis(d, modifyList(cfg, list(method = method, adjustment = if (method == "anova") "tukey" else "sidak", comparisons = if (method == "anova") "all" else "control")))
    invisible(lapply(result_sheets(z), sheet_frame)); invisible(analysis_report(z))
  }
  check(TRUE, "Arranged sheets and text reports render across parametric, lognormal, rank, normality and ROUT analyses")
  dir.create("artifacts/result-sheets", recursive = TRUE, showWarnings = FALSE)
  script <- normalizePath("artifacts/result-sheets", winslash = "/")
  writeLines(reproduction_script(d, modifyList(cfg, list(method = "outliers")), worksheet = worksheet), file.path(script, "reproduce.R"))
  old <- getwd(); on.exit(setwd(old), add = TRUE); setwd(script)
  e <- new.env(parent = globalenv()); sys.source("reproduce.R", envir = e); setwd(old)
  check(identical(cleaned_worksheet(e$result, e$worksheet)$Subject, wide$Subject) && file.exists(file.path(script, "sheet_cleaned_data.csv")), "Standalone export preserves arranged cleaned-data columns and original subject rows")
})
